/*
 * A097518  Zero-free Harshad left truncatable numbers.
 * https://oeis.org/A097518
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  fini, full, nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 25, u16 n <= 141, u32 n <= 1217, u64 n <= 3531,
 *            u128 n <= 3603, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A097518: zero‑free Harshad left‑truncatable numbers.
 * The sequence is generated by depth‑first search: start from every
 * one‑digit Harshad number (1‑9), then prepend a non‑zero digit
 * that keeps the resulting number divisible by its digit sum.
 * For 64‑bit types an overflow guard ensures that only representable
 * values are kept, preventing wrap‑around from corrupting the order.
 */
#include <stdbool.h>
#include <stdlib.h>

/* comparison for qsort */
static int cmp_seq(const void *a, const void *b)
{
    const seq_t *va = (const seq_t *)a;
    const seq_t *vb = (const seq_t *)b;
    if (*va < *vb) return -1;
    if (*va > *vb) return 1;
    return 0;
}

/* pre‑allocated storage – 5000 > max number of terms (3603) */
static seq_t seq[5000];
static size_t seq_cnt = 0;
static bool initialized = false;

/* DFS generator: current number, 10^len (power), sum of its digits */
static void generate(seq_t cur, seq_t power, seq_t sum)
{
    /* limit guard only for 8‑byte types; avoids overflow */
    static const bool USE_LIMIT = sizeof(seq_t) <= 8;

    for (int d = 1; d <= 9; ++d) {
        seq_t new_sum = sum + (seq_t)d;
        seq_t prod     = (seq_t)d * power;          /* d * 10^len */

        /* check for overflow when necessary */
        bool overflow = false;
        if (USE_LIMIT) {
            seq_t max_val = (seq_t)-1;               /* all bits one */
            if (power > max_val / (seq_t)d) overflow = true;   /* multiplication overflow */
            else if (cur > max_val - prod) overflow = true;    /* addition overflow */
        }
        if (overflow) continue;

        seq_t new_num = prod + cur;
        if (new_num % new_sum != 0) continue;          /* not a Harshad number */

        /* store the number */
        seq[seq_cnt++] = new_num;

        /* compute next power = power * 10 for recursion */
        seq_t next_power;
        if (USE_LIMIT) {
            seq_t max_val = (seq_t)-1;
            if (power > max_val / (seq_t)10) continue;   /* cannot recurse further */
            next_power = power * (seq_t)10;
        } else {
            next_power = power * (seq_t)10;
        }

        /* recurse with the new number as current */
        generate(new_num, next_power, new_sum);
    }
}

/* initialise the full sequence once */
static void init_sequence(void)
{
    seq_cnt = 0;

    /* single‑digit Harshads 1‑9 */
    for (int d = 1; d <= 9; ++d) {
        seq[seq_cnt++] = (seq_t)d;
        /* next power for a 1‑digit number is 10^1 = 10 */
        generate((seq_t)d, (seq_t)10, (seq_t)d);
    }

    /* sort ascending */
    qsort(seq, seq_cnt, sizeof(seq_t), cmp_seq);
    initialized = true;
}

/* public API */
seq_t a(idx_t n)
{
    if (!initialized) init_sequence();
    if (n == (idx_t)0 || (size_t)n > seq_cnt) return (seq_t)0;
    return seq[(size_t)(n - 1)];
}
